// Generate an AES-256 key from Qrypt quantum entropy.
// Run with: qrypt-run quickstart.mjs
import { createCipheriv, createDecipheriv, createHash, randomBytes } from "node:crypto";
import { writeFileSync } from "node:fs";

process.loadEnvFile(".env");
const token = process.env.QRYPT_API_KEY;
if (!token) throw new Error("QRYPT_API_KEY is not set in .env");

const baseUrl = process.env.QRYPT_BASE_URL ?? "https://api-eus.qrypt.com";
const url = new URL("/api/v1/quantum-entropy", baseUrl);
url.searchParams.set("size", "1"); // size is in KiB (1-512)

const res = await fetch(url, {
  headers: {
    Authorization: `Bearer ${token}`,
    Accept: "application/json",
    "User-Agent": "qrypt-aes256-quickstart/1.0",
    "X-Qrypt-Client": "quickstart",
  },
  signal: AbortSignal.timeout(15_000),
});

if (!res.ok) {
  const hints = {
    400: "size out of range (must be 1-512)",
    401: "Authorization header missing, malformed, or expired",
    403: "token invalid or monthly quota exhausted",
    429: "rate limited; wait 10s+ before retrying",
    500: "Qrypt server error; try again later",
    503: "Qrypt busy; try again later",
  };
  throw new Error(`Qrypt API ${res.status}: ${hints[res.status] ?? res.statusText}`);
}

const body = await res.json();
const entropy = Buffer.from(body.random[0], "base64");
if (entropy.length < 32) throw new Error(`Expected >= 32 bytes of entropy, got ${entropy.length}`);
const key = entropy.subarray(0, 32); // AES-256 key

// Sanity check: AES-256-GCM round trip with the new key.
const iv = randomBytes(12);
const plaintext = Buffer.from("hello, quantum world");
const cipher = createCipheriv("aes-256-gcm", key, iv);
const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
const decipher = createDecipheriv("aes-256-gcm", key, iv);
decipher.setAuthTag(cipher.getAuthTag());
const roundTrip = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
if (!roundTrip.equals(plaintext)) throw new Error("AES-GCM round trip failed");

// Store the key owner-only; never print it.
writeFileSync("aes256.key", key, { mode: 0o600 });

const fingerprint = createHash("sha256").update(key).digest("hex").slice(0, 16);
console.log(`AES-256 key generated from ${entropy.length} bytes of Qrypt quantum entropy`);
console.log(`Key length: ${key.length * 8} bits, saved to aes256.key (mode 600)`);
console.log(`SHA-256 fingerprint (first 16 hex): ${fingerprint}`);
console.log("AES-256-GCM encrypt/decrypt round trip: OK");

